import React, { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState('ru');
  const [emailNotifications, setEmailNotifications] = useState(true);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        maxWidth: '360px',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={name}
        onChange={(event) => setName(event.target.value)}
      />

      <JxSelect
        label="Язык интерфейса"
        options={LANGUAGE_OPTIONS}
        value={language}
        onValueChange={setLanguage}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <JxButton variant="primary" type="submit">
        Сохранить
      </JxButton>
    </form>
  );
}

